    const discographyHeading = Array.from(document.querySelectorAll('h2, h3')).find(h => h.textContent.includes('Studio albums') || (h.textContent.includes('Discography') && h.tagName === 'H2'));

    if (!discographyHeading) {
        return 'Could not find discography heading';
    }

    // Find the table after the studio albums heading
    let element = discographyHeading.nextElementSibling;
    while (element && element.tagName !== 'TABLE') {
        element = element.nextElementSibling;
    }

    if (!element || element.tagName !== 'TABLE') {
        return 'Could not find studio albums table';
    }

    // Extract table data
    const rows = element.querySelectorAll('tr');
    const albums = [];

    for (let i = 1; i < rows.length; i++) { // Skip header row
        const cells = rows[i].querySelectorAll('td, th');
        if (cells.length >= 2) {
            const yearCell = cells[0];
            const albumCell = cells[1];

            const yearText = yearCell.textContent.trim();
            const albumText = albumCell.textContent.trim();

            // Try to extract year as number
            const yearMatch = yearText.match(/(\d{4})/);
            const year = yearMatch ? parseInt(yearMatch[1]) : null;

            if (year && albumText) {
                // Clean up album title (remove "Label: ..." part)
                const albumTitle = albumText.split('Label:')[0].trim();
                albums.push({ year, title: albumTitle });
            }
        }
    }

    return {
        totalCount: albums.length,
        albums: albums
    };
}"}

