{"function": "() => {
    // Find the studio albums table
    const tables = document.querySelectorAll('table.wikitable');
    let studioAlbumsTable = null;

    for (const table of tables) {
        const text = table.textContent;
        if (text.includes('La Voz de la Zafra') && text.includes('1962')) {
            studioAlbumsTable = table;
            break;
        }
    }

    if (!studioAlbumsTable) {
        return 'Studio albums table not found';
    }

    // Extract all rows from the table
    const rows = studioAlbumsTable.querySelectorAll('tr');
    const albums = [];

    // Skip the header row (if it exists)
    const startIndex = rows[0].querySelector('th') ? 1 : 0;

    for (let i = startIndex; i < rows.length; i++) {
        const cells = rows[i].querySelectorAll('td');
        if (cells.length >= 2) {
            const yearCell = cells[0];
            const albumCell = cells[1];

            const yearText = yearCell.textContent.trim();
            const albumText = albumCell.textContent.trim();

            // Extract year - look for 4-digit number
            const yearMatch = yearText.match(/(\d{4})/);
            const year = yearMatch ? parseInt(yearMatch[1]) : null;

            if (year && albumText) {
                // Clean up album title: remove "Label: ..." part and any HTML tags
                let albumTitle = albumText;

                // Remove "Label: ..." if present
                const labelIndex = albumTitle.indexOf('Label:');
                if (labelIndex !== -1) {
                    albumTitle = albumTitle.substring(0, labelIndex).trim();
                }

                // Remove any parenthesized content like "(w/various artists)" or "(w/Charly García)"
                albumTitle = albumTitle.replace(/\s*\([^)]*\)/g, '').trim();

                // Remove italic markup if present in text form
                albumTitle = albumTitle.replace(/''/g, '').trim();

                albums.push({
                    year: year,
                    title: albumTitle,
                    rawText: albumText // Keep raw for debugging
                });
            }
        }
    }

    return {
        totalAlbums: albums.length,
        allAlbums: albums,
        albums2000to2009: albums.filter(album => album.year >= 2000 && album.year <= 2009)
    };
}"}

