            const yearMatch = yearText.match(/(\d{4})/);
            const year = yearMatch ? parseInt(yearMatch[1]) : null;

            if (year && albumText) {
                // Clean up album title: remove "Label: ..." part and any HTML tags
                let albumTitle = albumText;

                // Remove "Label: ..." if present
                const labelIndex = albumTitle.indexOf('Label:');
                if (labelIndex !== -1) {
                    albumTitle = albumTitle.substring(0, labelIndex).trim();
                }

                // Remove any parenthesized content like "(w/various artists)" or "(w/Charly García)"
                albumTitle = albumTitle.replace(/\s*\([^)]*\)/g, '').trim();

                // Remove italic markup if present in text form
                albumTitle = albumTitle.replace(/''/g, '').trim();

                albums.push({
                    year: year,
                    title: albumTitle,
                    rawText: albumText // Keep raw for debugging
                });
            }
        }
    }

    return {
        totalAlbums: albums.length,
        allAlbums: albums,
        albums2000to2009: albums.filter(album => album.year >= 2000 && album.year <= 2009)
    };
}"}

