                    }

                    albumTitle = albumTitle.replace(/\s*\([^)]*\)/g, '').trim();
                    albumTitle = albumTitle.replace(/''/g, '').trim();

                    compAlbums.push({
                        year: year,
                        title: albumTitle,
                        type: 'compilation',
                        rawText: albumText
                    });
                }
            }
        }
    }

    return {
        liveAlbums: liveAlbums.filter(album => album.year >= 2000 && album.year <= 2009),
        compAlbums: compAlbums.filter(album => album.year >= 2000 && album.year <= 2009),
